   135	async function findClaims(videoId: string, title: string, cues: Cue[]) {
   136	  if (cues.length === 0) return setStatus({ state: "noCaptions" });
   137	  setStatus({ state: "finding" });
   138	  const response = await askServer<FindClaimsResponse>({
   139	    type: "findClaims",
   140	    videoId,
   141	    title,
   142	    transcript: transcriptText(cues),
   143	  });
   144	  if (videoId !== currentVideoId()) return;
   145	  if (!response.ok) {
   146	    return setStatus({
   147	      state: "error",
   148	      reason: `Couldn't find claims: ${response.error}`,
   149	      retry: () => void findClaims(videoId, title, cues),
   150	    });
   151	  }
   152	  const claims = response.claims
   153	    .flatMap((claim): LiveClaim[] => {
   154	      const lineStart = parseTime(claim.time);
   155	      if (lineStart === null) return [];
   156	      const seconds = quoteStart(cues, claim.quote, lineStart);
   157	      return [{ ...claim, seconds, check: { state: "waiting" }, chip: "none" }];
   158	    })
   159	    .sort((a, b) => a.seconds - b.seconds);
