   165	/** Starts checks for the next claims within LOOKAHEAD_SECONDS of the playhead. */
   166	function checkAhead(): void {
   167	  const video = playerVideo();
   168	  if (status.state !== "ready" || !video || adShowing()) return;
   169	  const now = video.currentTime;
   170	  const { claims } = status;
   171	  const running = claims.filter((claim) => claim.check.state === "checking");
   172	  claims
   173	    .filter(
   174	      (claim) =>
   175	        claim.check.state === "waiting" &&
   176	        claim.seconds > now - CHIP_WINDOW_SECONDS &&
   177	        claim.seconds < now + LOOKAHEAD_SECONDS,
   178	    )
   179	    .slice(0, Math.max(0, PARALLEL_CHECKS - running.length))
   180	    .forEach((claim) => void checkClaim(claim));
   181	}
