   183	async function checkClaim(claim: LiveClaim): Promise<void> {
   184	  if (status.state !== "ready") return;
   185	  const { videoId, title } = status;
   186	  claim.check = { state: "checking" };
   187	  renderList();
   188	  const { time, quote, claim: text } = claim;
   189	  const response = await askServer<CheckClaimResponse>({
   190	    type: "checkClaim",
   191	    videoId,
   192	    title,
   193	    claim: { time, quote, claim: text },
   194	  });
   195	  claim.check = response.ok
   196	    ? { state: "done", verdict: response.verdict }
   197	    : { state: "failed", error: response.error };
   198	  if (videoId !== currentVideoId()) return;
   199	  renderList();
   200	  showDueChips();
   201	  checkAhead();
   202	}
