   204	function verdictLook(claim: LiveClaim): { label: string; tone: Tone } {
   205	  switch (claim.check.state) {
   206	    case "waiting":
   207	      return { label: "Not checked yet", tone: "grey" };
   208	    case "checking":
   209	      return { label: "Checking…", tone: "grey" };
   210	    case "failed":
   211	      return { label: "Couldn't check", tone: "grey" };
   212	    case "done": {
   213	      const { verdict } = claim.check.verdict;
   214	      if (verdict === "supported") return { label: "Supported", tone: "green" };
   215	      if (verdict === "unverified")
   216	        return { label: "Unverified", tone: "grey" };
   217	      const label = verdict === "contradicted" ? "Contradicted" : "Misleading";
   218	      return { label, tone: "red" };
   219	    }
   220	  }
   221	}
