   223	/** Shows a chip for each claim being said now, with its verdict once there is one. */
   224	function showDueChips(): void {
   225	  const video = playerVideo();
   226	  if (status.state !== "ready" || !video || adShowing()) return;
   227	  const now = video.currentTime;
   228	  for (const claim of status.claims) {
   229	    const due =
   230	      claim.seconds <= now && now < claim.seconds + CHIP_WINDOW_SECONDS;
   231	    if (!due || claim.chip === "final") continue;
   232	    const settled =
   233	      claim.check.state === "done" || claim.check.state === "failed";
   234	    if (settled || claim.chip === "none") showChip(claim);
   235	    claim.chip = settled ? "final" : "pending";
   236	  }
   237	}
