   239	function showChip(claim: LiveClaim): void {
   240	  const player = document.getElementById("movie_player");
   241	  if (!player) return;
   242	  let chips = document.getElementById(CHIPS_ID);
   243	  if (!chips) {
   244	    chips = element("div");
   245	    chips.id = CHIPS_ID;
   246	  }
   247	  if (chips.parentElement !== player) player.append(chips);
   248	
   249	  const look =
   250	    claim.check.state === "waiting"
   251	      ? { label: "Checking…", tone: "grey" as const }
   252	      : verdictLook(claim);
   253	  const chip =
   254	    chipsByClaim.get(claim) ?? element("button", undefined, "vfc-chip");
   255	  chipsByClaim.set(claim, chip);
   256	  chip.type = "button";
   257	  chip.dataset.tone = look.tone;
   258	  chip.title = `${look.label}: ${claim.claim}`;
   259	  chip.classList.remove("vfc-leaving");
   260	  chip.replaceChildren(
   261	    element("strong", look.tone === "green" ? "✓ Supported" : look.label),
   262	  );
   263	  // Only red flags spell out the claim; the others stay small and quiet.
   264	  if (look.tone === "red") chip.append(element("span", claim.claim));
   265	  chip.onclick = (event) => {
   266	    event.stopPropagation(); // Not a click on the video.
   267	    void openFromChip(claim);
   268	  };
   269	  if (!chip.isConnected) chips.append(chip);
   270	
   271	  clearTimeout(chipTimers.get(chip));
   272	  const shown = look.tone === "red" ? RED_CHIP_MS : QUIET_CHIP_MS;
   273	  chipTimers.set(
   274	    chip,
   275	    window.setTimeout(() => {
   276	      chip.classList.add("vfc-leaving");
   277	      chipTimers.set(
   278	        chip,
   279	        window.setTimeout(() => chip.remove(), 400),
   280	      );
   281	    }, shown),
   282	  );
   283	}
